@pytest.mark.parametrize("ending", [b"\r\n", b"\r", b"\n"])
@pytest.mark.parametrize("padding", [b"", b" \t" * 40])
@pytest.mark.parametrize("closing_newline", [False, True])
def test_decoder_fragmented_delimiters(ending, padding, closing_newline):
    boundary = b"b.o+u(n)d?a$"
    payload = b"\0\r\n\r" + b"".join(
        ending + b"--" + boundary + suffix
        for suffix in (b"--X", b"--!", b"---", b"----", b" \tX", b"-- \tX")
    )
    values = [payload, b"", b"last\r"]
    body = b"preamble" + ending
    for value in values:
        body += (
            b"--" + boundary + padding + ending
            + b'Content-Disposition: form-data; name="same"; filename="a.bin"'
            + ending + b"X-Test: yes" + ending + ending + value + ending
        )
    body += b"--" + boundary + b"--" + padding
    if closing_newline:
        body += ending

    def decode(chunks):
        decoder = MultipartDecoder(boundary)
        parts = []
        events = []
        for chunk in [*chunks, None]:
            decoder.receive_data(chunk)
            while True:
                event = decoder.next_event()
                if isinstance(event, NeedData):
                    break
                if isinstance(event, Data):
                    parts[-1] += event.data
                    if not event.more_data:
                        events.append(bytes(parts[-1]))
                else:
                    events.append(event)
                    if isinstance(event, File):
                        parts.append(bytearray())
                if isinstance(event, Epilogue):
                    break
        return events

    expected = [Preamble(b"preamble")]
    for value in values:
        expected.extend(
            [
                File(
                    name="same",
                    filename="a.bin",
                    headers=Headers(
                        [
                            (
                                "Content-Disposition",
                                'form-data; name="same"; filename="a.bin"',
                            ),
                            ("X-Test", "yes"),
                        ]
                    ),
                ),
                value,
            ]
        )
    expected.append(Epilogue(b""))
    assert decode([body]) == expected
    for split in range(len(body) + 1):
        assert decode([body[:split], body[split:]]) == expected
    assert decode([body[i : i + 1] for i in range(len(body))]) == expected


@pytest.mark.parametrize("padding", [b"", b" \t" * 40])
@pytest.mark.parametrize("suffix", [None, b"\r\n", b"X\r\n--foo--\r\n"])
def test_decoder_closing_requires_line_or_eof(padding, suffix):
    decoder = MultipartDecoder(b"foo")
    decoder.receive_data(
        b'--foo\r\nContent-Disposition: form-data; name="x"\r\n\r\n'
        + b"x" * 100 + b"\r\n--foo--" + padding
    )
    assert isinstance(decoder.next_event(), Preamble)
    assert isinstance(decoder.next_event(), Field)
    data = bytearray()
    while True:
        event = decoder.next_event()
        if isinstance(event, NeedData):
            break
        assert isinstance(event, Data) and event.more_data
        data.extend(event.data)
    assert data  # Ordinary payload streams before closure is confirmed.
    decoder.receive_data(suffix)
    while True:
        event = decoder.next_event()
        if isinstance(event, Data):
            data.extend(event.data)
            if not event.more_data:
                break
        else:
            pytest.fail(f"Unexpected event: {event}")
    expected = b"x" * 100
    if suffix is not None and suffix.startswith(b"X"):
        expected += b"\r\n--foo--" + padding + b"X"
    assert data == expected
    if suffix is not None:
        decoder.receive_data(None)
    assert decoder.next_event() == Epilogue(b"")
