@pytest.mark.parametrize("read_size", [1, 7, 65536])
@pytest.mark.parametrize("use_request", [False, True])
def test_fragmented_multipart_payload_and_metadata(read_size, use_request):
    class FragmentedStream(io.BytesIO):
        def read(self, size=-1):
            return super().read(read_size if size < 0 else min(size, read_size))

        def readinto(self, buffer):
            return super().readinto(memoryview(buffer)[:read_size])

    boundary = b"b.o+u(n)d?a$"
    fields = [b"\0\r\n\r", b"", b"last\n"]
    files = [b"\0" * 65535 + b"\r", b"", b"\r\n--" + boundary + b"--X\0\n"]
    body = bytearray()
    for field, file in zip(fields, files):
        body.extend(
            b"--" + boundary + b" \t\r\n"
            b'Content-Disposition: form-data; name="field"\r\n\r\n'
            + field + b"\r\n"
            b"--" + boundary + b"\t \r\n"
            b'Content-Disposition: form-data; name="file"; filename="a.bin"\r\n'
            b"Content-Type: application/octet-stream\r\n"
            b"X-Test: yes\r\n\r\n" + file + b"\r\n"
        )
    body.extend(b"--" + boundary + b"-- \t")
    stream = FragmentedStream(body)
    if use_request:
        request = Request.from_values(
            input_stream=stream,
            content_length=len(body),
            content_type='multipart/form-data; boundary="b.o+u(n)d?a$"',
            method="POST",
        )
        form, uploads = request.form, request.files
    else:
        _, form, uploads = FormDataParser().parse(
            stream, "multipart/form-data", len(body), {"boundary": boundary.decode()}
        )
    try:
        assert form.getlist("field") == [value.decode() for value in fields]
        assert [file.read() for file in uploads.getlist("file")] == files
        for file in uploads.getlist("file"):
            assert file.name == "file"
            assert file.filename == "a.bin"
            assert file.content_type == "application/octet-stream"
            assert file.headers["X-Test"] == "yes"
    finally:
        for file in uploads.getlist("file"):
            file.close()
        if use_request:
            request.close()
