    def _find_boundary(
        self, data: bytes | bytearray, *, preamble: bool = False, start: int = 0
    ) -> tuple[tuple[int, int, bool] | None, int]:
        # Keep enough trailing bytes for any incomplete delimiter prefix,
        # including its leading CRLF. A complete prefix followed by an
        # incomplete suffix (possibly arbitrarily long padding) is kept below.
        safe_end = max(0, len(data) - len(self.boundary) - SEARCH_EXTRA_LENGTH)
        pattern = self.preamble_re if preamble else self.boundary_re
        for match in pattern.finditer(data, start):
            pos = match.end()
            closing = data[pos : pos + 2] == b"--"
            if closing:
                pos += 2
            elif data[pos : pos + 1] == b"-":
                if pos + 1 == len(data) and not self.complete:
                    return None, min(safe_end, match.start())
                continue

            while pos < len(data) and data[pos] in b" \t":
                pos += 1

            if pos == len(data):
                if closing and self.complete:
                    return (match.start(), pos, True), safe_end
                if not self.complete:
                    return None, min(safe_end, match.start())
                continue

            if data[pos] == 0x0D:
                # Do not mistake the first half of CRLF for a legacy CR.
                if pos + 1 == len(data) and not self.complete:
                    return None, min(safe_end, match.start())
                pos += 1
                if data[pos : pos + 1] == b"\n":
                    pos += 1
            elif data[pos] == 0x0A:
                pos += 1
            else:
                # A boundary lookalike is ordinary payload. Continue looking
                # for a later, valid delimiter without discarding any bytes.
                continue

            return (match.start(), pos, closing), safe_end

        return None, safe_end

    def _parse_data(
        self, data: bytes | bytearray, *, start: bool
    ) -> tuple[bytes, int, bool]:
        # Body parts start with a separator line break. A trailing CR can
        # still become CRLF, so leave it untouched until the next read.
        if start:
            if not data or (data == b"\r" and not self.complete):
                return b"", 0, True
            match = LINE_BREAK_RE.match(data)
            if match is None:
                raise ValueError("Missing newline at start of part")
            data_start = match.end()
        else:
            data_start = 0

        match, safe_end = self._find_boundary(data)
        if match is not None:
            data_end, del_index, closing = match
            self.state = State.EPILOGUE if closing else State.PART
            return bytes(data[data_start:data_end]), del_index, False

        # An empty part can use the separator itself as the delimiter's
        # leading line break. Keep it until that possibility is resolved.
        if safe_end < data_start:
            return b"", 0, True
        return bytes(data[data_start:safe_end]), safe_end, True


